from trudag.dotstop.core.item import Item


def item_from_dict(data: dict) -> Item:
    """
    Helper function for creating a Item from a dictionary object.
    """
    return Item(
        name=data["name"],
        text=data.get("text", ""),
        normative=data.get("normative", True),
        unresolved_references=data.get("references"),
        resolved_references=data.get("resolved_references"),
        validator_config=data.get("evidence"),
        sme_scores=data.get("score"),
        order=data.get("order"),
    )
